// تعريف فئة لتخزين وتتبع تفضيلات المستخدم
class UserPreferences {
    constructor() {
        this.preferences = {};
    }

    // دالة لتخزين تفضيل المستخدم
    setPreference(key, value) {
        this.preferences[key] = value;
        this.savePreferences();
    }

    // دالة لاسترجاع تفضيل المستخدم
    getPreference(key) {
        return this.preferences[key];
    }

    // دالة لحفظ التفضيلات في التخزين المحلي (Local Storage)
    savePreferences() {
